def resolve_permissions(role: str, parents: dict[str,str], grants: dict[str,list[str]]) -> list[str] | None:
    """Resolve a role's permissions by collecting grants from the role and all its parents,
    deduplicating, and sorting. Rejects unknown roles, unknown parents, or inheritance cycles."""
    if role not in grants:
        return None
    role_grants = set(grants[role])
    visited = set()
    queue = [parents[role]]
    while queue:
        parent = queue.pop(0)
        if parent in visited:
            return None
        visited.add(parent)
        if parent in grants:
            for g in grants[parent]:
                if g not in role_grants:
                    role_grants.add(g)
        queue.append(parents[parent])
    return sorted(role_grants)

